+// Package spec loads language-neutral generation rules. It has no Go runtime SDK dependencies.
+package spec
+
+import (
+ "bytes"
+ "fmt"
+ "io"
+ "os"
+ "path/filepath"
+ "gopkg.in/yaml.v3"
+)
+
+type Validation struct { Version int `yaml:"version"`; Messages map[string]Message `yaml:"messages"` }
+type Message struct { Fields map[string]Field `yaml:"fields"`; Constraints []Constraint `yaml:"constraints"` }
+type Field struct {
+ Minimum *float64 `yaml:"minimum"`; ExclusiveMinimum *float64 `yaml:"exclusive_minimum"`; Maximum *float64 `yaml:"maximum"`
+ Finite bool `yaml:"finite"`; Nonblank bool `yaml:"nonblank"`; Each bool `yaml:"each"`; MinItems *int `yaml:"min_items"`
+}
+type Condition struct { Field string `yaml:"field"`; Equals *int `yaml:"equals"`; NotEquals *int `yaml:"not_equals"` }
+type Constraint struct { Op string `yaml:"op"`; Field string `yaml:"field"`; Other string `yaml:"other"`; Fields []string `yaml:"fields"`; When *Condition `yaml:"when"` }
+type Type struct { Import string `yaml:"import"`; Name string `yaml:"name"` }
+type Mapping struct { From string `yaml:"from"`; To string `yaml:"to"`; Transform string `yaml:"transform"`; Factor uint64 `yaml:"factor"`; Maximum *uint64 `yaml:"maximum"`; Cast string `yaml:"cast"` }
+type Group struct { Name string `yaml:"name"`; Source Type `yaml:"source"`; Target Type `yaml:"target"`; Direction string `yaml:"direction"`; Fields []Mapping `yaml:"fields"` }
+type Provider struct { Version int `yaml:"version"`; Provider string `yaml:"provider"`; Groups []Group `yaml:"groups"` }
+
+func decode(path string, value any) error {
+ data,err:=os.ReadFile(path);if err!=nil{return err}
+ decoder:=yaml.NewDecoder(bytes.NewReader(data));decoder.KnownFields(true)
+ if err=decoder.Decode(value);err!=nil{return fmt.Errorf("%s: %w",path,err)}
+ var extra any
+ if err=decoder.Decode(&extra);err!=io.EOF{return fmt.Errorf("%s: expected exactly one YAML document",path)}
+ return nil
+}
+func LoadValidation(root string)(Validation,error){var v Validation;err:=decode(filepath.Join(root,"validation.yaml"),&v);if err==nil&&v.Version!=1{err=fmt.Errorf("unsupported validation spec version %d",v.Version)};return v,err}
+func LoadProvider(root,name string)(Provider,error){var p Provider;err:=decode(filepath.Join(root,"providers",name+".yaml"),&p);if err==nil&&(p.Version!=1||p.Provider!=name){err=fmt.Errorf("invalid provider spec version/identity: %s",name)};return p,err}
+
+// Tags translates portable field rules into the Go validator dialect.
+func Tags(rule Field, optional bool, repeated bool) string {
+ var tags []string
+ if optional{tags=append(tags,"omitnil")}
+ if rule.MinItems!=nil{tags=append(tags,fmt.Sprintf("min=%d",*rule.MinItems))}
+ if rule.Each{tags=append(tags,"dive")}
+ if rule.Finite{tags=append(tags,"finite")}
+ if rule.Nonblank{tags=append(tags,"nonblank")}
+ if rule.Minimum!=nil{tags=append(tags,fmt.Sprintf("gte=%g",*rule.Minimum))}
+ if rule.ExclusiveMinimum!=nil{tags=append(tags,fmt.Sprintf("gt=%g",*rule.ExclusiveMinimum))}
+ if rule.Maximum!=nil{tags=append(tags,fmt.Sprintf("lte=%g",*rule.Maximum))}
+ if repeated&&!rule.Each{tags=append(tags,"dive","required")}
+ return strings.Join(tags,",")
+}
