 native,err:=sdk.NewClientWithOptions(&params);if err!=nil{return nil,err}
 return &Adapter{client:native,scope:&core.ClientContext{AppName:core.Value(config.GetContext().GetAppName()),Environment:core.Value(config.GetContext().GetEnvironment())},region:config.GetRegion()},nil
