func mapInitialization(config *core.ClientConfig)(sdk.ClientParams,error){
 var params sdk.ClientParams
 if config==nil{config=&core.ClientConfig{}}
 if err:=core.ValidateClientConfig(config);err!=nil{return params,err}
 if config.Endpoint!=nil{return params,fmt.Errorf("sandbox-kit modal: Endpoint cannot be configured through this SDK's public client constructor")}
 scope:=config.GetContext()
