  remaining:=*scope;remaining.AppName,remaining.Environment=nil,nil
  if err:=core.RejectUnmapped("modal client context",&remaining);err!=nil{return params,err}
  params.Environment=scope.GetEnvironment()
 }
 auth:=config.GetAuth()
 if auth==nil{return params,nil}
 switch{
 case auth.TokenPair!=nil:
  mapped,remaining,err:=mapTokenPairAuth(auth.TokenPair);if err!=nil{return params,err}
  if err:=core.RejectUnmapped("modal token pair",&remaining);err!=nil{return params,err}
  params.TokenID,params.TokenSecret=mapped.TokenID,mapped.TokenSecret
