  if err:=core.RejectUnmapped("modal OAuth",&remaining);err!=nil{return params,err}
  params.OAuthCredentials=&mapped
 default:return params,fmt.Errorf("sandbox-kit modal: use token-pair or OAuth-refresh authentication")
 }
 return params,nil
}
